<script setup lang="ts">
import {ref,computed,watch,nextTick,useId,onDeactivated,onBeforeUnmount} from 'vue';
import {parseDateText,formatChineseDate,calendarDays,dateValue} from '../chinese-date';
const props=withDefaults(defineProps<{modelValue:string;label:string;placeholder:string;min?:string;max?:string;required?:boolean;hideLabel?:boolean}>(),{min:'',max:'',required:false,hideLabel:false});
const emit=defineEmits<{'update:modelValue':[value:string]}>();
const id=useId(),input=ref<HTMLInputElement|null>(null),panel=ref<HTMLElement|null>(null),open=ref(false),focused=ref(false),text=ref(formatChineseDate(props.modelValue));
const currentDate=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date());
const today=ref(currentDate());
const initial=props.modelValue||today.value,year=ref(Number(initial.slice(0,4))),month=ref(Number(initial.slice(5,7))),location=ref({left:'0px',top:'0px'});
const cells=computed(()=>calendarDays(year.value,month.value));
const allowed=(value:string)=>(!props.min||value>=props.min)&&(!props.max||value<=props.max);
function validity(){const value=parseDateText(text.value);input.value?.setCustomValidity(!text.value?'':!value?'请选择有效日期，或填写如 2026年10月27日 的日期。':!allowed(value)?'日期不在允许范围内，请重新选择。':'');}
watch(()=>[props.modelValue,props.min,props.max],()=>{if(!focused.value)text.value=formatChineseDate(props.modelValue);void nextTick(validity);});
function typed(){const value=parseDateText(text.value);emit('update:modelValue',value||'');validity();}
function blurred(){focused.value=false;if(parseDateText(text.value))text.value=formatChineseDate(text.value);validity();}
function hide(restore=false){panel.value?.hidePopover();open.value=false;if(restore)input.value?.focus({preventScroll:true});}
function choose(value:string){if(value&&(!parseDateText(value)||!allowed(value)))return;text.value=formatChineseDate(value);emit('update:modelValue',value);hide(true);void nextTick(()=>{validity();input.value?.dispatchEvent(new Event('change',{bubbles:true}));});}
async function show(){if(open.value){hide(true);return;}today.value=currentDate();const selected=parseDateText(props.modelValue)||today.value;year.value=Number(selected.slice(0,4));month.value=Number(selected.slice(5,7));const bounds=input.value!.getBoundingClientRect(),height=Math.min(360,innerHeight-16);location.value={left:Math.max(8,Math.min(bounds.left,innerWidth-328))+'px',top:Math.max(8,bounds.bottom+height+8<=innerHeight?bounds.bottom+5:bounds.top-height-5)+'px'};panel.value?.showPopover();open.value=true;await nextTick();const control=panel.value?.querySelector<HTMLElement>('.date-day[aria-selected="true"]:not(:disabled),.date-day:not(:disabled)');control?.focus({preventScroll:true});}
function chooseToday(){today.value=currentDate();choose(today.value);}
function move(delta:number){const index=year.value*12+month.value-1+delta;const y=Math.floor(index/12);if(y>=1&&y<=9999){year.value=y;month.value=index%12+1;}}
function setYear(event:Event,commit=false){const value=Number((event.target as HTMLInputElement).value);if(Number.isInteger(value)&&value>=1&&value<=9999)year.value=value;else if(commit)(event.target as HTMLInputElement).value=String(year.value);}
onDeactivated(()=>hide());onBeforeUnmount(()=>hide());
</script>
<template><div class="chinese-date"><label :for="id" :class="{'sr-only':hideLabel}">{{label}}</label><div class="chinese-date-control"><input :id="id" ref="input" type="text" :value="text" :placeholder="placeholder" :required="required" autocomplete="off" :aria-expanded="open" aria-haspopup="dialog" :aria-controls="id+'-calendar'" @focus="focused=true" @blur="blurred" @input="text=($event.target as HTMLInputElement).value;typed()" @keydown.down.prevent="show"><button type="button" class="date-trigger" :aria-label="'选择'+label" @click="show"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 5h14v16H5zM8 2v6M16 2v6M5 10h14"/></svg></button></div>
<div :id="id+'-calendar'" ref="panel" popover="auto" class="chinese-calendar" :style="location" role="dialog" :aria-label="'选择'+label" @toggle="open=($event as ToggleEvent).newState==='open'" @keydown.esc.stop.prevent="hide(true)"><div class="calendar-heading"><button type="button" class="secondary" aria-label="上个月" @click="move(-1)">‹</button><label><input aria-label="年份" type="number" :value="year" min="1" max="9999" @change.stop="setYear($event,true)" @input.stop="setYear($event)" @keydown.enter.stop.prevent="setYear($event,true)">年</label><label><select aria-label="月份" v-model.number="month" @change.stop><option v-for="m in 12" :key="m" :value="m">{{m}}月</option></select></label><button type="button" class="secondary" aria-label="下个月" @click="move(1)">›</button></div><div class="calendar-grid"><span v-for="day in ['一','二','三','四','五','六','日']" :key="day" class="calendar-weekday">{{day}}</span><template v-for="(day,index) in cells" :key="index"><button v-if="day" type="button" :aria-label="formatChineseDate(dateValue(year,month,day))" :aria-selected="modelValue===dateValue(year,month,day)" :disabled="!allowed(dateValue(year,month,day))" class="date-day" @click="choose(dateValue(year,month,day))">{{day}}</button><span v-else/></template></div><div class="calendar-footer"><button type="button" class="text-button" :disabled="!allowed(today)" @click="chooseToday">今天</button><button type="button" class="text-button" @click="choose('')">清除</button><button type="button" class="secondary" @click="hide(true)">关闭</button></div></div></div></template>
